#include "ArrangementTools.h"
#include "ControlEdits.h"
static void testSectionClips(const File& root,Assets& assets){
    auto sample=root.getChildFile("section-source.wav");{AudioBuffer<float> audio(2,120000);for(int i=0;i<audio.getNumSamples();++i){audio.setSample(0,i,(float)(.3*std::sin(i*.071)));audio.setSample(1,i,(float)(.2*std::sin(i*.043)));}TemporaryFile temp(sample);std::unique_ptr<OutputStream> stream(temp.getFile().createOutputStream());auto writer=WavAudioFormat().createWriterFor(stream,AudioFormatWriterOptions{}.withSampleRate(48000).withNumChannels(2).withBitsPerSample(32));expect(writer&&writer->writeFromAudioSampleBuffer(audio,0,audio.getNumSamples()),"write a stereo source fixture for section arrangement");writer.reset();expect(temp.overwriteTargetFileWithTemporary(),"commit section source fixture atomically");}
    auto source=emptyProject();source.songMode=true;source.bpm=120;source.loop=false;for(auto& t:source.tracks)t.send=0;source.patterns[0].length=4;source.patterns[0].lanes[7]={{0,1,60,.8f}};source.markers={{"verse","Verse",4,8,2},{"cue","Cue",6,-1,3}};source.loopSection="verse";
    Clip audio;audio.track=6;audio.pattern=999;audio.beat=5;audio.length=2;audio.audioPath=sample.getFullPathName();audio.sourceOffset=.125;audio.gain=.5f;audio.fadeIn=.25;audio.fadeOut=.5;
    Clip automation;automation.track=2;automation.pattern=999;automation.beat=4;automation.length=4;automation.automationTarget=0;automation.automationTrack=7;automation.points={{0,.2f,false},{2,.7f,true},{4,.4f,false}};
    source.clips={{7,0,0,4},{7,0,4,4},audio,automation,{7,0,8,4}};auto original=JSON::toString(projectToJson(source));auto hash=SHA256(sample).toHexString();Project out;SectionClipStats stats;
    expect(inspectSectionClips(source,"verse",stats).wasOk()&&stats.sourceIndices==std::vector<int>({1,2,3})&&stats.patternClips==1&&stats.audioClips==1&&stats.automationClips==1&&stats.automationPoints==3,"section scope includes every wholly-contained pattern/audio/automation clip in source order");
    expect(stats.start==4&&stats.end==8,"section scope uses exact half-open marker bounds");
    expect(transformSectionClips(source,"verse",16,false,false,out,&stats).wasOk()&&out.clips.size()==8&&stats.resultIndices==std::vector<int>({5,6,7})&&stats.destination==16,"Copy appends all complete section clips and reports their result indices");
    expect(out.clips[5].beat==16&&out.clips[6].beat==17&&out.clips[7].beat==16&&out.clips[5].track==7&&out.clips[6].track==6,"Copy retains relative positions and Playlist lanes");
    const auto& copy=out.clips[6];expect(copy.pattern==999&&copy.audioPath==audio.audioPath&&copy.sourceOffset==.125&&copy.gain==.5f&&copy.fadeIn==.25&&copy.fadeOut==.5,"section audio copies retain the complete source/range/gain/fade payload");
    const auto& copiedAutomation=out.clips[7];expect(copiedAutomation.pattern==999&&copiedAutomation.automationTrack==7&&copiedAutomation.automationTarget==0&&copiedAutomation.points.size()==3&&copiedAutomation.points[1].beat==2&&copiedAutomation.points[1].value==.7f&&copiedAutomation.points[1].hold,"section automation copies retain the display lane, target link and relative point/hold data");
    expect(out.loopSection==source.loopSection&&out.activePattern==source.activePattern&&out.songMode==source.songMode&&out.patterns[0].editorId==source.patterns[0].editorId&&JSON::toString(projectToJson(out)["markers"])==JSON::toString(projectToJson(source)["markers"]),"section clip editing preserves markers, loop link, PAT/Song mode and source pattern identity");
    auto manual=source;manual.clips.push_back({7,0,16,4});auto movedAudio=audio;movedAudio.beat=17;manual.clips.push_back(movedAudio);auto movedAutomation=automation;movedAutomation.beat=16;manual.clips.push_back(movedAutomation);expect(render(out,assets,root,500000,127)==render(manual,assets,root,500000,512),"mixed section copies render like an explicitly authored arrangement across callback sizes");
    expect(transformSectionClips(source,"verse",16,true,false,out,&stats).wasOk()&&out.clips.size()==5&&stats.resultIndices==stats.sourceIndices&&out.clips[1].beat==16&&out.clips[2].beat==17&&out.clips[3].beat==16&&out.clips[0].beat==0&&out.clips[4].beat==8,"Move relocates original indices atomically and leaves all other clips in place");
    expect(JSON::toString(projectToJson(source))==original&&SHA256(sample).toHexString()==hash,"arrangement operations never mutate their const source or source audio file");
    auto file=root.getChildFile("section-arranged.pulse");Project loaded;expect(saveProject(out,file).wasOk()&&loadProject(file,loaded).wasOk()&&JSON::toString(projectToJson(out))==JSON::toString(projectToJson(loaded)),"mixed section moves round-trip with unchanged project schema 14");
    auto sentinel=JSON::toString(projectToJson(out));stats.patternClips=99;auto reject=[&](const Project& p,const String& id,double at,bool move=false,bool overlaps=false){return transformSectionClips(p,id,at,move,overlaps,out,&stats).failed()&&JSON::toString(projectToJson(out))==sentinel&&stats.patternClips==99;};
    expect(reject(source,"missing",16)&&reject(source,"cue",16),"missing sections and point markers cannot silently define a clip range");
    for(double at:{-1.,4093.,4096.,4.,std::numeric_limits<double>::infinity(),std::numeric_limits<double>::quiet_NaN()})expect(reject(source,"verse",at),"invalid, overflowing and unchanged destinations fail atomically");
    auto straddle=source;straddle.clips.push_back({0,0,3,2});expect(reject(straddle,"verse",16),"a clip crossing the source start blocks the entire edit");straddle=source;straddle.clips.push_back({0,0,7,2});expect(reject(straddle,"verse",16),"a clip crossing the source end blocks the entire edit");straddle=source;straddle.clips.push_back({0,0,0,12});expect(reject(straddle,"verse",16),"a clip enclosing the source section is never silently omitted or trimmed");
    auto empty=source;empty.clips={source.clips[0],source.clips[4]};expect(reject(empty,"verse",16),"clips only touching the source edges leave an empty section and create no undo-worthy edit");
    expect(reject(source,"verse",0)&&reject(source,"verse",5),"Copy rejects destination collisions with existing clips on the same Playlist lane");
    expect(transformSectionClips(source,"verse",0,false,true,out).wasOk()&&out.clips.size()==8&&out.clips[0].beat==0&&out.clips[5].beat==0,"explicit layering preserves every destination clip instead of overwriting it");
    auto overlapMove=source;overlapMove.clips.pop_back();expect(transformSectionClips(overlapMove,"verse",5,true,false,out).wasOk()&&out.clips.size()==4&&out.clips[1].beat==5,"Move ignores the old positions of its own clips when moving to a partially overlapping source range");
    auto otherLane=source;otherLane.clips.push_back({1,0,16,4});expect(transformSectionClips(otherLane,"verse",16,false,false,out).wasOk(),"destination clips on independent Playlist lanes do not block the edit");
    auto touching=source;touching.clips.push_back({7,0,20,4});expect(transformSectionClips(touching,"verse",16,false,false,out).wasOk(),"a destination clip starting at the copied end does not overlap");
    sentinel=JSON::toString(projectToJson(out));auto linked=source;auto competing=automation;competing.track=3;competing.beat=16;linked.clips.push_back(competing);expect(reject(linked,"verse",16),"default overlap guards include the same automation parameter even on another display lane");competing.automationTrack=6;linked.clips.back()=competing;expect(transformSectionClips(linked,"verse",16,false,false,out).wasOk(),"automation targeting an independent channel on another lane does not conflict");
    auto master=source;master.clips[3].automationTarget=5;master.clips[3].automationTrack=-1;competing=master.clips[3];competing.track=3;competing.automationTrack=7;competing.beat=16;master.clips.push_back(competing);sentinel=JSON::toString(projectToJson(out));expect(reject(master,"verse",16),"Master automation conflicts ignore its semantically unused target-track field");
    auto fractional=source;expect(transformSectionClips(fractional,"verse",12.125,false,false,out).wasOk()&&out.clips[5].beat==12.125&&out.clips[6].beat==13.125,"fractional destination beats retain exact relative offsets without snapping");
    expect(transformSectionClips(source,"verse",4092,false,false,out).wasOk()&&out.clips[5].beat+out.clips[5].length==4096,"a destination ending exactly at beat 4096 is supported");
    auto alias=source;expect(transformSectionClips(alias,"verse",16,true,false,alias).wasOk()&&alias.clips[1].beat==16&&alias.patterns[0].editorId==source.patterns[0].editorId,"in-place section transforms preserve project identities without invalid references");
    sentinel=JSON::toString(projectToJson(out));auto full=source;while(full.clips.size()<maxClips)full.clips.push_back({1,0,100,1});expect(reject(full,"verse",16),"Copy enforces the global 512-clip capacity before changing anything");expect(transformSectionClips(full,"verse",16,true,false,alias).wasOk()&&alias.clips.size()==512,"Move still works when the Playlist is full because it allocates no clip slots");
    auto autoFull=source;while(std::count_if(autoFull.clips.begin(),autoFull.clips.end(),[](const Clip& c){return c.isAutomation();})<maxAutomationClips){auto extra=automation;extra.beat=100;autoFull.clips.push_back(extra);}expect(reject(autoFull,"verse",16),"Copy enforces the automation-clip capacity independently of total clips");
    auto pointsFull=source;pointsFull.clips[3].points.clear();for(int i=0;i<256;++i)pointsFull.clips[3].points.push_back({i*4./255,.5f,false});for(int i=0;i<15;++i){auto extra=pointsFull.clips[3];extra.beat=100;pointsFull.clips.push_back(extra);}expect(reject(pointsFull,"verse",16),"Copy enforces the total automation-point budget before appending");expect(transformSectionClips(pointsFull,"verse",16,true,false,alias).wasOk(),"Move retains the same automation-point budget at capacity");
    auto broken=source;broken.clips[1].pattern=99;expect(reject(broken,"verse",16),"invalid genuine pattern references are rejected without touching ignored audio pattern fields");broken=source;broken.clips[2].sourceOffset=-1;expect(reject(broken,"verse",16),"invalid audio source ranges cannot enter a section copy");broken=source;broken.clips[3].points[1].value=2;expect(reject(broken,"verse",16),"invalid automation values fail before transformation");broken=source;broken.markers[0].endBeat=3;expect(reject(broken,"verse",16),"invalid section bounds fail before touching clips");
    broken=source;broken.patterns[0].lanes.pop_back();expect(reject(broken,"verse",16),"invalid pattern lane shapes fail before native playback can access them");
    expect(applyControlEdits(source,JSON::parse(R"([{"op":"section_clips","section":"verse","destination":16}])"),out).wasOk()&&out.clips.size()==8&&out.clips[5].beat==16,"MCP section_clips defaults to Copy with overlap rejection");
    expect(applyControlEdits(source,JSON::parse(R"([{"op":"section_clips","section":"verse","destination":0,"move":true,"allowOverlap":true}])"),out).wasOk()&&out.clips.size()==5&&out.clips[1].beat==0,"MCP Move and explicit destination layering retain the same core semantics");
    sentinel=JSON::toString(projectToJson(out));for(auto json:{R"([{"op":"section_clips","section":"verse","destination":16,"move":1}])",R"([{"op":"section_clips","section":"verse","destination":16,"allowOverlap":"yes"}])",R"([{"op":"section_clips","section":"verse","destination":16,"replace":true}])",R"([{"op":"section_clips","section":"verse","destination":16},{"op":"set_pattern","pattern":99,"name":"bad"}])"})expect(applyControlEdits(source,JSON::parse(json),out).failed()&&JSON::toString(projectToJson(out))==sentinel,"MCP rejects wrong fields/types and later batch failures atomically");
}
